UPDATE T_INQUIRY
   SET AI_TYPE       = #{aiType}
      ,AI_AREA       = #{aiArea}
      ,AI_SEVERITY   = #{aiSeverity}
      ,AI_SUMMARY    = #{aiSummary}
      ,AI_FIX_HINT   = #{aiFixHint}
      ,AI_REPLY      = #{aiReply}
      ,AUTOFIX       = #{autofix}
      ,RISK_FLAGS    = #{riskFlags}
      ,TRIAGE_STATUS = #{triageStatus}
      ,TRIAGED_DAY   = NOW()
 WHERE ID = #{id}

UPDATE T_INQUIRY
   SET REPLY       = #{reply}
      ,REPLIED_BY  = #{adminId}
      ,REPLIED_DAY = NOW()
      ,STATUS      = #{status}
 WHERE ID = #{id}
